/**
 * DEV — Identify Notion Change
 *
 * Receives only signature-verified webhook events.
 * Classifies Sessions, Assignments and Facilitators.
 * No external writes.
 */

const SOURCES = {
  "655cf0f3-93cd-4d72-920a-ad0805d06242": "Session",
  "d31c840a-3bcf-4113-97dc-1526ebb9eac6": "Assignment",
  "c08cd0af-3a20-4bf5-9deb-b2f3db272ab9": "Facilitator"
};

const results = [];

for (const item of $input.all()) {

  // Read the original payload from the Webhook node.
  const incoming = $("Webhook").first().json.body;

  const event = typeof incoming === "string"
    ? JSON.parse(incoming)
    : incoming;

  // Only property-update events are relevant.
  if (event?.type !== "page.properties_updated") {
    continue;
  }

  const pageId = event.entity?.id ?? null;
  const parent = event.data?.parent ?? {};

  const dataSourceId =
    parent.data_source_id ??
    (parent.type === "data_source" ? parent.id : null) ??
    parent.id ??
    null;

  const entityType = SOURCES[dataSourceId] ?? null;

  const properties = Array.isArray(
    event.data?.updated_properties
  )
    ? event.data.updated_properties
    : [];

  results.push({
    json: {
      eventId: event.id ?? null,
      eventType: event.type,
      changedAt: event.timestamp ?? null,
      pageId,
      dataSourceId,
      entityType,
      changedPropertyIds: properties,
      changedPropertyCount: properties.length,
      origin: "Notion",
      attemptNumber: event.attempt_number ?? 1,
      classification:
        !pageId
          ? "REVIEW_MISSING_PAGE"
          : !entityType
            ? "REVIEW_UNKNOWN_SOURCE"
            : properties.length === 0
              ? "REVIEW_NO_PROPERTIES"
              : "IDENTIFIED",
      safeToWrite: false
    }
  });
}

return results;

const event = $("DEV — Identify Notion Change").first().json;
const schema = $input.first().json;

function normaliseId(id) {
  try {
    return decodeURIComponent(String(id ?? ""));
  } catch {
    return String(id ?? "");
  }
}

const definitions = Object.entries(schema.properties ?? {});

const changedProperties = event.changedPropertyIds.map(id => {
  const match = definitions.find(([name, property]) =>
    normaliseId(property.id) === normaliseId(id)
  );

  return {
    propertyId: id,
    propertyName: match?.[0] ?? null,
    propertyType: match?.[1]?.type ?? null
  };
});

return [{
  json: {
    ...event,
    changedProperties,
    allPropertiesResolved: changedProperties.every(
      p => p.propertyName !== null
    ),
    safeToWrite: false
  }
}];

/**
 * DEV — Classify Notion Sync Fields
 *
 * Classifies verified, resolved Notion changes.
 * No data writes or sync authorisation.
 */

const FIELD_RULES = {
  Session: {
    "Event Date": {
      action: "SYNC_CANDIDATE",
      googleField: "Date"
    },
    "Instance Status": {
      action: "SYNC_CANDIDATE",
      googleField: "Session Status"
    },
    "Instance Notes": {
      action: "NOTION_ONLY",
      googleField: null
    },
    "Event Instance": {
      action: "TITLE_MAINTENANCE",
      googleField: null
    }
  },
  Assignment: {},
  Facilitator: {}
};

return $input.all().map(item => {
  const event = item.json;
  const rules = FIELD_RULES[event.entityType] ?? {};

  const classifiedFields =
    (event.changedProperties ?? []).map(property => {
      const rule = rules[property.propertyName];

      return {
        ...property,
        action: rule?.action ?? "REVIEW_MAPPING",
        googleField: rule?.googleField ?? null
      };
    });

  return {
    json: {
      ...event,
      classifiedFields,
      requiresSync: classifiedFields.some(
        f => f.action === "SYNC_CANDIDATE"
      ),
      requiresReview: classifiedFields.some(
        f => f.action === "REVIEW_MAPPING"
      ),
      decision:
        !event.allPropertiesResolved
          ? "REVIEW"
          : classifiedFields.some(
              f => f.action === "REVIEW_MAPPING"
            )
            ? "REVIEW"
            : classifiedFields.some(
                f => f.action === "SYNC_CANDIDATE"
              )
              ? "SYNC_CANDIDATE"
              : "NO_SYNC_REQUIRED",
      safeToWrite: false
    }
  };
});

const pages = $input.all();

return pages.map(item => {
  const page = item.json;

  const event = $("DEV — Classify Notion Sync Fields")
    .first().json;

  const property = page.properties?.["Session External ID"];

  let externalId = null;

  if (property?.type === "rich_text") {
    externalId = property.rich_text
      .map(part => part.plain_text)
      .join("")
      .trim();
  } else if (property?.type === "title") {
    externalId = property.title
      .map(part => part.plain_text)
      .join("")
      .trim();
  }

  const valid = Boolean(
    externalId &&
    /^BR-S-\d{6}$/.test(externalId) &&
    page.id === event.pageId
  );

  return {
    json: {
      ...event,
      externalId,
      identityValid: valid,
      decision: valid
        ? event.decision
        : "REVIEW_IDENTITY",
      safeToWrite: false
    }
  };
});

const pending = $('DEV — Read Pending Sync Events').first().json;
const sessionId = pending.external_id;

const events = $input.all()
  .map(item => item.json)
  .filter(e =>
    e.external_id === sessionId &&
    ['Google', 'Notion'].includes(e.origin) &&
    !Number.isNaN(Date.parse(e.changed_at))
  )
  .sort((a, b) =>
    Date.parse(b.changed_at) - Date.parse(a.changed_at)
  );

if (!events.length) {
  return [{
    json: {
      sessionId,
      decision: 'REVIEW_NO_HISTORY',
      safeToWrite: false
    }
  }];
}

const latest = events[0];

const dateField = (latest.changed_fields ?? [])
  .find(f =>
    f.field === 'Date' ||
    f.propertyName === 'Event Date'
  );

return [{
  json: {
    sessionId,
    latestEventId: latest.id,
    latestOrigin: latest.origin,
    latestChangedAt: latest.changed_at,
    proposedDate: dateField?.newValue ?? null,
    decision: latest.origin === 'Google'
      ? 'GOOGLE_LATEST_RECORDED_EDIT'
      : 'NOTION_LATEST_RECORDED_EDIT',
    requiresCurrentValueCheck: true,
    safeToWrite: false
  }
}];

/**
 * Stage 9 Pt. 3 — Session Date Direction
 * DEV decision preview. No updates or status changes.
 */

const pending = $('DEV — Read Pending Sync Events').first().json;
const history = $('DEV — Read Session Date Event History')
  .all().map(item => item.json);

const googleRows = $('DEV — Verify Current Google Session Date')
  .all().map(item => item.json);

const notion = $('DEV — Verify Current Notion Session Date')
  .first().json;

const sessionId = pending.external_id;

const dateOnly = value =>
  typeof value === 'string'
    ? value.slice(0, 10)
    : null;

function result(decision, reason, extra = {}) {
  return [{
    json: {
      sessionId,
      decision,
      reason,
      ...extra,
      safeToWrite: false
    }
  }];
}

// Verify canonical identity in both systems.
const matches = googleRows.filter(
  row => row['Session ID'] === sessionId
);

if (
  matches.length !== 1 ||
  notion.id !== pending.notion_page_id
) {
  return result(
    'REVIEW_IDENTITY',
    'Google or Notion identity could not be verified'
  );
}

const googleDate = dateOnly(matches[0].Date);

const notionExternalId = (
  notion.properties?.['Session External ID']
    ?.rich_text ?? []
).map(part => part.plain_text ?? part.text?.content ?? '')
 .join('').trim();

const notionDate = dateOnly(
  notion.properties?.['Event Date']?.date?.start
);

if (
  notionExternalId !== sessionId ||
  !googleDate ||
  !notionDate
) {
  return result(
    'REVIEW_VALUES',
    'Notion external ID or current dates are missing'
  );
}

// Use recorded property-level events, not page timestamps,
// to determine the latest known deliberate edit.
const dateEvents = history
  .filter(e =>
    e.external_id === sessionId &&
    ['Google', 'Notion'].includes(e.origin) &&
    (e.changed_fields ?? []).some(f =>
      f.field === 'Date' ||
      f.propertyName === 'Event Date'
    ) &&
    Number.isFinite(Date.parse(e.changed_at))
  )
  .sort((a, b) =>
    Date.parse(b.changed_at) -
    Date.parse(a.changed_at)
  );

if (!dateEvents.length) {
  return result('REVIEW_HISTORY', 'No valid edit history');
}

const latest = dateEvents[0];
const second = dateEvents[1] ?? null;

const latestField = latest.changed_fields.find(
  f => f.field === 'Date' ||
       f.propertyName === 'Event Date'
);

const proposedDate = latest.origin === 'Google'
  ? dateOnly(latestField.newValue)
  : notionDate;

const sourceDate = latest.origin === 'Google'
  ? googleDate
  : notionDate;

const targetDate = latest.origin === 'Google'
  ? notionDate
  : googleDate;

const direction = latest.origin === 'Google'
  ? 'GOOGLE_TO_NOTION'
  : 'NOTION_TO_GOOGLE';

// Reject equal-timestamp competing events.
if (
  second &&
  Date.parse(second.changed_at) ===
    Date.parse(latest.changed_at) &&
  second.origin !== latest.origin
) {
  return result(
    'REVIEW_ORDER',
    'Competing edits have indistinguishable timestamps'
  );
}

if (!proposedDate || sourceDate !== proposedDate) {
  return result(
    'REVIEW_SOURCE_CHANGED',
    'Current source value does not match latest edit'
  );
}

// Page timestamp is a conservative warning only.
// It is not proof of a property-level edit.
const notionPageTime = Date.parse(
  notion.last_edited_time
);

const latestTime = Date.parse(latest.changed_at);

if (
  latest.origin === 'Google' &&
  Number.isFinite(notionPageTime) &&
  notionPageTime > latestTime
) {
  return result(
    'REVIEW_LATER_NOTION_ACTIVITY',
    'Notion page has activity newer than the Google edit'
  );
}

return result(
  targetDate === proposedDate
    ? 'ALREADY_MATCHED'
    : direction,
  targetDate === proposedDate
    ? 'Both systems already hold the proposed value'
    : 'Latest recorded edit matches its current source value',
  {
    winningOrigin: latest.origin,
    winningEventId: latest.id,
    winningEventStatus: latest.status,
    winningChangedAt: latest.changed_at,
    proposedDate,
    googleDate,
    notionDate,
    notionPageLastEdited: notion.last_edited_time,
    requiresEligibilityApproval: latest.status === 'REVIEW',
    requiresCurrentValueCheck: false
  }
);

const d = $input.first().json;

const approved =
  /^BR-S-\d{6}$/.test(d.sessionId ?? '') &&
  /^\d+$/.test(String(d.winningEventId ?? '')) &&
  d.winningEventStatus === 'RECEIVED' &&
  (
    (d.decision === 'GOOGLE_TO_NOTION' &&
     d.winningOrigin === 'Google') ||
    (d.decision === 'NOTION_TO_GOOGLE' &&
     d.winningOrigin === 'Notion')
  ) &&
  /^\d{4}-\d{2}-\d{2}$/.test(d.proposedDate ?? '') &&
  d.googleDate !== d.notionDate &&
  d.requiresEligibilityApproval === false &&
  d.requiresCurrentValueCheck === false;

return [{
  json: {
    ...d,
    testApproved: approved,
    approvalScope: approved
      ? 'DEV_ELIGIBLE_SESSION_DATE'
      : 'NONE',
    safeToWrite: false
  }
}];

/**
 * Stage 9 — Reusable Session Date writer gate
 * DEV only; processes one selected event.
 */

const operation = $input.first().json;
const approval = $('DEV — Authorise Session Date Test').first().json;

const history = $('DEV — Read Session Date Event History')
  .all().map(item => item.json);

const googleRows = $('DEV — Verify Current Google Session Date')
  .all().map(item => item.json);

const notion = $('DEV — Verify Current Notion Session Date')
  .first().json;

const event = history.find(e =>
  String(e.id) === String(approval.winningEventId)
);

const matches = googleRows.filter(g =>
  g['Session ID'] === approval.sessionId
);

const google = matches.length === 1 ? matches[0] : null;

const dateOnly = value =>
  typeof value === 'string' ? value.slice(0, 10) : null;

const googleDate = dateOnly(google?.Date);
const notionDate = dateOnly(
  notion.properties?.['Event Date']?.date?.start
);

const notionExternalId = (
  notion.properties?.['Session External ID']?.rich_text ?? []
).map(t => t.plain_text ?? t.text?.content ?? '')
 .join('').trim();

const direction = approval.decision;

const targetSystem =
  direction === 'GOOGLE_TO_NOTION' ? 'Notion' :
  direction === 'NOTION_TO_GOOGLE' ? 'Google' :
  null;

const sourceDate =
  direction === 'GOOGLE_TO_NOTION' ? googleDate :
  direction === 'NOTION_TO_GOOGLE' ? notionDate :
  null;

const targetDate =
  direction === 'GOOGLE_TO_NOTION' ? notionDate :
  direction === 'NOTION_TO_GOOGLE' ? googleDate :
  null;

const expectedTargetDate =
  direction === 'GOOGLE_TO_NOTION'
    ? approval.notionDate
    : approval.googleDate;

const checks = {
  approved: approval.testApproved === true,

  scope:
    approval.approvalScope === 'DEV_ELIGIBLE_SESSION_DATE',

  session:
    /^BR-S-\d{6}$/.test(approval.sessionId ?? ''),

  event:
    !!event &&
    String(operation.event_id) === String(event.id) &&
    event.status === 'RECEIVED',

  operationPending: operation.status === 'PENDING',

  target: operation.target_system === targetSystem,

  field: operation.field_name === 'Date',

  identity:
    operation.external_id === approval.sessionId &&
    google?.['Session ID'] === approval.sessionId &&
    notionExternalId === approval.sessionId,

  origin:
    event?.origin === approval.winningOrigin,

  source:
    sourceDate === approval.proposedDate,

  targetValue:
    targetDate === expectedTargetDate,

  value:
    operation.attempted_value === approval.proposedDate,

  changeRequired:
    sourceDate !== targetDate
};

const authorised = Object.values(checks).every(Boolean);

return [{
  json: {
    operationId: operation.id,
    eventId: operation.event_id,
    sessionId: approval.sessionId,
    notionPageId: notion.id,
    direction,
    targetSystem,
    proposedDate: approval.proposedDate,
    expectedPreviousDate: expectedTargetDate,
    checks,
    decision: authorised
      ? 'AUTHORISE_DEV_WRITE'
      : 'HOLD_FOR_REVIEW',
    safeToWrite: authorised,
    failedChecks: Object.entries(checks)
      .filter(([, passed]) => !passed)
      .map(([name]) => name)
  }
}];
